  x: {label: "Renda da casa (padronizada) →", domain: [-3.5, 3.5]},
  y: {label: "Proporção das casas", grid: true, tickFormat: ".0%"},
  color: {domain: ["Southwark and Vauxhall", "Lambeth"], range: [pal.award, pal.accent], legend: true},
  marks: [
    Plot.areaY(dens, {x: "x", y1: 0, y2: "y", fill: "grupo", fillOpacity: 0.18, curve: "step"}),
