### Em R


::: {.cell}

```{.r .cell-code}
set.seed(7919)
n <- 50000; a <- -5.8; b <- 2.1; c <- 0.8; gama <- 0
renda <- rnorm(n)
sv <- rbinom(n, 1, plogis(-gama * renda))        # 1 = Southwark and Vauxhall
q1 <- plogis(a + b - c * renda)                  # risco se recebesse água de S&V
q0 <- plogis(a - c * renda)                      # risco se recebesse água da Lambeth
morte <- rbinom(n, 1, ifelse(sv == 1, q1, q0))

razao_ingenua <- mean(morte[sv == 1]) / mean(morte[sv == 0])
efeito_verdadeiro <- mean(q1) / mean(q0)
c(ingenua = razao_ingenua, verdadeira = efeito_verdadeiro)
```
